ON CONFLICT (customer_id) DO UPDATE SET
  customer_name = EXCLUDED.customer_name,
  city = EXCLUDED.city;

SELECT setval(pg_get_serial_sequence('public.dim_customer', 'customer_id'), coalesce((SELECT max(customer_id) FROM public.dim_customer), 1));

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='fact_order_items')
     AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_customer') THEN
    ALTER TABLE public.fact_order_items ADD CONSTRAINT fk_customer FOREIGN KEY (customer_id) REFERENCES public.dim_customer(customer_id);
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


-- NexaCart Emergency Recovery: fact_order_items
-- Run in Supabase SQL editor to restore fact_order_items (10,000 transactions)
CREATE TABLE IF NOT EXISTS public.fact_order_items (
  order_item_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_number text NOT NULL,
  order_date date NOT NULL,
  customer_id bigint,
  product_id bigint,
  seller_id bigint,
  payment_id bigint,
  shipping_id bigint,
  quantity integer NOT NULL CHECK (quantity > 0),
  unit_price numeric NOT NULL CHECK (unit_price >= 0::numeric),
  discount_amount numeric DEFAULT 0 CHECK (discount_amount >= 0::numeric),
  shipping_fee numeric DEFAULT 0 CHECK (shipping_fee >= 0::numeric),
  gross_sales numeric GENERATED ALWAYS AS (round(((quantity)::numeric * unit_price), 2)) STORED,
  net_sales numeric GENERATED ALWAYS AS (round((((quantity)::numeric * unit_price) - discount_amount), 2)) STORED,
  total_paid numeric GENERATED ALWAYS AS (round(((((quantity)::numeric * unit_price) - discount_amount) + shipping_fee), 2)) STORED,
  CONSTRAINT valid_discount CHECK (discount_amount <= ((quantity)::numeric * unit_price))
);

ALTER TABLE public.fact_order_items ENABLE ROW LEVEL SECURITY;
GRANT ALL ON public.fact_order_items TO service_role;
GRANT SELECT ON public.fact_order_items TO anon, authenticated;

