ON CONFLICT (order_item_id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.fact_order_items', 'order_item_id'), coalesce((SELECT max(order_item_id) FROM public.fact_order_items), 1));

-- Attach foreign keys if dimensions exist
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='dim_seller') AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_seller') THEN
    ALTER TABLE public.fact_order_items ADD CONSTRAINT fk_seller FOREIGN KEY (seller_id) REFERENCES public.dim_seller(seller_id);
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='dim_customer') AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_customer') THEN
    ALTER TABLE public.fact_order_items ADD CONSTRAINT fk_customer FOREIGN KEY (customer_id) REFERENCES public.dim_customer(customer_id);
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='dim_product') AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_product') THEN
    ALTER TABLE public.fact_order_items ADD CONSTRAINT fk_product FOREIGN KEY (product_id) REFERENCES public.dim_product(product_id);
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='dim_payment') AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_payment') THEN
    ALTER TABLE public.fact_order_items ADD CONSTRAINT fk_payment FOREIGN KEY (payment_id) REFERENCES public.dim_payment(payment_id);
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='dim_shipping') AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_shipping') THEN
    ALTER TABLE public.fact_order_items ADD CONSTRAINT fk_shipping FOREIGN KEY (shipping_id) REFERENCES public.dim_shipping(shipping_id);
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';

